pub fn company_scope_paths(reducer_name: &str) -> &'static [CompanyScopePath] {
    match reducer_name {
        "apply_historical_payment_allocations" => &[CompanyScopePath { parameter_position: 1, path: &["company_id"], required: true, nullable: false }],
        "create_account_account" => &[CompanyScopePath { parameter_position: 1, path: &["company_id"], required: true, nullable: false }],
        "create_contact" => &[CompanyScopePath { parameter_position: 1, path: &["company_id"], required: false, nullable: true }],
        "create_manual_account_invoice" => &[CompanyScopePath { parameter_position: 1, path: &["company_id"], required: true, nullable: false }],
        "create_opportunity" => &[CompanyScopePath { parameter_position: 1, path: &["company_id"], required: false, nullable: true }],
        "create_whatsapp_business_account" => &[CompanyScopePath { parameter_position: 1, path: &["company_id"], required: false, nullable: true }],
        _ => &[],
    }
}

